//! GENERATED by cer/tools/gen-intl.cjs from engine/LocaleData.rgr,
//! engine/LocalePlural.rgr, engine/UnicodeCollate.rgr and
//! engine/UnicodeTailor.rgr; supplement() from the host's ICU.

