/// a table by name, empty for an unknown one
pub fn table(name: &str) -> String {
    if name == "supplement" {
        return supplement();
    }
    if name == "tags" {
        return tags();
    }
    if name == "num_strings" {
        return num_strings();
    }
    if name == "num_ints" {
        return num_ints();
    }
    if name == "names" {
        return names();
    }
    if name == "pattern_ints" {
        return pattern_ints();
    }
    if name == "pattern_strings" {
        return pattern_strings();
    }
    if name == "currency_strings" {
        return currency_strings();
    }
    if name == "currency_ints" {
        return currency_ints();
    }
    if name == "currency_count" {
        return currency_count();
    }
    if name == "plural_keys" {
        return plural_keys();
    }
    if name == "plural_entries" {
        return plural_entries();
    }
    if name == "plural_pairs" {
        return plural_pairs();
    }
    if name == "list_separators" {
        return list_separators();
    }
    if name == "punct_runs" {
        return punct_runs();
    }
    if name == "expansions" {
        return expansions();
    }
    if name == "mark_ranks" {
        return mark_ranks();
    }
    if name == "base_letters" {
        return base_letters();
    }
    if name == "tailor_locales" {
        return tailor_locales();
    }
    if name == "tailor_entries" {
        return tailor_entries();
    }
    String::new()
}

/// whether the table of that name holds strings
pub fn is_strings(name: &str) -> bool {
    name == "supplement" || name == "tags" || name == "num_strings" || name == "names" || name == "pattern_strings" || name == "currency_strings" || name == "plural_keys" || name == "list_separators"
}
